<script setup lang="ts">
type Niche = { _id: string; name: string; description: string }; type Angle = { _id: string; code?: string; nicheId: string | { _id: string }; name: string; description: string; riskLevel?: string }
const niches = ref<Niche[]>([]); const angles = ref<Angle[]>([]); const selectedNiche = ref(''); const selectedAngle = ref(''); const error = ref(''); const product = useState('product'); const country = useState('country')
const risk: Record<string, string> = { LOW: 'bg-emerald-100 text-emerald-700', MEDIUM: 'bg-amber-100 text-amber-700', HIGH: 'bg-orange-100 text-orange-700', EXTREME: 'bg-red-100 text-red-700' }
const riskLabel: Record<string, string> = { LOW: 'Bajo', MEDIUM: 'Medio', HIGH: 'Alto', EXTREME: 'Extremo' }
async function loadNiches() { try { niches.value = await $fetch<Niche[]>('/api/niches', { query: { active: true } }); selectedNiche.value ||= niches.value[0]?._id || ''; await loadAngles() } catch (e: any) { error.value = e?.data?.statusMessage || 'No se pudo cargar el banco.' } }
async function loadAngles() { if (!selectedNiche.value) return; angles.value = await $fetch<Angle[]>('/api/angles', { query: { nicheId: selectedNiche.value, active: true } }); if (!angles.value.some(x => x._id === selectedAngle.value)) selectedAngle.value = angles.value[0]?._id || '' }
watch(selectedNiche, loadAngles); onMounted(loadNiches)
const currentAngle = computed(() => angles.value.find(x => x._id === selectedAngle.value))
</script>
